# This formula is regenerated by the ankra-cli release workflow from
# packaging/homebrew/ankra.rb.tmpl in ankraio/ankra-cli. Manual edits here
# will be overwritten on the next release; change the template instead.
#
# There is deliberately no `version` stanza: `brew audit` fails a tap whose
# declared version it can already scan from the stable URL (redundant_version),
# and every release URL below carries the tag. That is why the URLs interpolate
# nothing - the release workflow substitutes the version into them directly.
class Ankra < Formula
  desc "Command-line interface for the Ankra Kubernetes platform"
  homepage "https://ankra.io"
  license "Apache-2.0"

  livecheck do
    url :stable
    strategy :github_latest
  end

  on_macos do
    on_arm do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.74.0/ankra-cli-darwin-arm64"
      sha256 "4b3b4133b987bc96efbc76346f94686efccb3fc3b1cf94c4b7bdd5e245f12ffc"
    end
    on_intel do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.74.0/ankra-cli-darwin-amd64"
      sha256 "83c6da6c96f69c46c47368f3edaeb83db8d620babfe07e9cc65c636c2c0f9eff"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.74.0/ankra-cli-linux-arm64"
      sha256 "4fa31b7c965dd12a06c64ca5bb778de6360110dd874e3aa1f5d3f317d8a4b087"
    end
    on_intel do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.74.0/ankra-cli-linux-amd64"
